"""BetterAgent: SimplifyAgent plus switchable additions (each a small method, off by its class constant).

0. GUARD_C_OPEN + HEALTH_ESTIMATE. In a strategic / bottleneck case C charges for the supplier's margin below
   `sustainable_margin_pct`; `total_cost` without a supplier estimate sees 0 (real P02 v17: 140k health cost, c_deal >
   c_open, score 0). The estimate here comes from the data package only: full cost = the should-cost row of the
   part (the supplier's own row, else the generic one), as a BAND (BAND_SPECIFIC / BAND_GENERIC, wider for a supplier
   whose credit index fell or equity is thin); interest rate = the buyer's. It is set through cost.HEALTH for the whole
   decision, so price choice, caps, closing rule and stall jump all see the health term; prices minimise the C expected
   over the band; no offer or accept may exceed c_open at the band's pessimistic end; an accept must also be the best
   complete package (against the alternative and the standing sheets of the other threads).
1. THIRD_SHEET: a third equivalent sheet (shorter payment or another contract length, price lowered to equal C).
2. ANCHOR_BY_SHARE: first offer = max(floor, price x (1 - share x index drop)) where the case data show a drop.
3. CASH_SHORT: a cash-short supplier gets shorter payment days against a lower price.
4. LATE_ACCEPT: with <= 2 messages left, accept a standing sheet within 1% of the best known C.
5. HOLD_FOR_FINAL: no accept while the supplier's latest message is a plain "open" offer with >= HOLD_MESSAGES
   messages left, unless it repeated its price (its floor): we keep countering until it sends final_offer.
Rival-quote citation (RESEARCH rule 12) is not here: EvidenceAgent._rewrite already cites the best real rival offer ID."""

import math
import re
from contextlib import contextmanager
from contextvars import ContextVar

from ..cost import HEALTH, complete_offer, cost_breakdown, must_haves_ok, total_cost
from ..docs import standard_terms
from ..evidence import _q, load_package
from ..guard import satisfy_must_haves
from ..play import find_sheet, latest, moves_left, standing
from . import simplify_agent
from .reciprocal import ANCHOR_FLOOR, FRAC0, FRAC_MAX, FRAC_STEP, KEEP, MIN_STEP, MOVING_MIN, _c_alt, _live, _mine, _pinned, _sheets, _sup, _tick
from .simplify_agent import FREE_LEVERS, SimplifyAgent, _health_at_stake

CASH_SHORT = re.compile(r"liquidity|working[- ]capital|cash[- ]?flow|short of cash|cash[- ]?(?:tight|short|constrain|crunch)", re.I)

HOLD = ContextVar("hold", default=None)  # set while BetterAgent decides: (case, threads, decision) -> True to veto a close (see _vetoes)


def _gate(real):
    """simplify's decide() starts with the closing rule; this lets BetterAgent veto it (only inside its own decide)."""
    def closing_accept(case, threads, *a, **k):
        r = real(case, threads, *a, **k)
        hold = HOLD.get()
        return None if r and hold and hold(case, threads, r) else r
    return closing_accept


simplify_agent.closing_accept = _gate(simplify_agent.closing_accept)


BAND_SPECIFIC = 0.03  # +-3% around the should-cost: the row is a bottom-up estimate of this supplier's plant
BAND_GENERIC = 0.08  # +-8% when only the generic (German cost base) row exists: another plant, another cost base
BAND_WEAK = 0.02  # extra width for a supplier with a falling credit index or equity below WEAK_EQUITY: its real cost is less certain
WEAK_EQUITY = 20.0  # equity ratio, %


def _health(case):
    """{full_cost, interest_rate, band: (lo, hi) multipliers of full_cost} of the supplier for cost.HEALTH, or None
    (no relationship cost / no should-cost row). Only the data package and the case are used."""
    if not _health_at_stake(case) or not (pkg := load_package()):
        return None
    try:
        rows = _q(pkg, "select supplier_id, unit_cost, price_unit from should_cost where part_id=?", case["parts"][0])
    except Exception:
        return None
    suppliers = case.get("suppliers", [])
    own = [r for r in rows if r["supplier_id"] in suppliers]
    row = next(iter(own or [r for r in rows if not r["supplier_id"]] or rows), None)  # own row, else the generic one, else any
    if not row:
        return None
    width = (BAND_SPECIFIC if own else BAND_GENERIC) if BetterAgent.BAND else 0.0  # BAND off: the centre estimate only
    try:
        intel = _q(pkg, "select equity_ratio_pct, credit_index, credit_index_12m_ago from supplier_intel where supplier_id=?", row["supplier_id"] or (suppliers or [None])[0])
        if intel and ((intel[0]["credit_index"] or 0) < (intel[0]["credit_index_12m_ago"] or 0) or (100 if intel[0]["equity_ratio_pct"] is None else intel[0]["equity_ratio_pct"]) < WEAK_EQUITY):
            width += BAND_WEAK * (width > 0)
    except Exception:
        pass
    return {"full_cost": row["unit_cost"] / (row["price_unit"] or 1), "interest_rate": case["buyer"]["interest_rate"], "band": (1 - width, 1 + width)}


@contextmanager
def _with_health(case, on=True):
    token = HEALTH.set(_health(case) if on else None)
    try:
        yield
    finally:
        HEALTH.reset(token)


@contextmanager
def _ensure_health(case):
    """The ambient estimate, or this case's own when none is set."""
    if HEALTH.get() is None:
        with _with_health(case):
            yield
    else:
        yield


@contextmanager
def _scaled(k):
    """The estimate's full cost x k (k = 1: unchanged)."""
    est = HEALTH.get()
    token = HEALTH.set({**est, "full_cost": est["full_cost"] * k}) if est and k != 1 else None
    try:
        yield
    finally:
        if token:
            HEALTH.reset(token)


def _c_at(case, t, std, k=None):
    """C with the supplier's full cost x k; default k = the band's pessimistic end (C rises with the full cost)."""
    est = HEALTH.get() or {}
    with _scaled(est.get("band", (1, 1))[1] if k is None else k):
        return total_cost(case, t, std)


def _exp_c(case, t, std):
    """C expected over the band (lower end, estimate, upper end equally weighted): what prices are chosen by."""
    lo, hi = (HEALTH.get() or {}).get("band", (1, 1))
    return sum(_c_at(case, t, std, k) for k in (lo, 1, hi)) / 3


def _num(x):
    return None if x is None or x == math.inf else round(x, 2)


def _sheet_of(ev, d):
    """The terms a decision accepts or offers first, else None."""
    msg = d.get("message") or {}
    if (act := msg.get("action") or {}).get("type") == "accept":
        return find_sheet(ev, act.get("term_sheet_id"))
    return msg["term_sheets"][0]["terms"] if msg.get("term_sheets") else None


def _best_standing(case, threads, skip=None, k=None):
    """(C at the pessimistic end (k: another multiple of the full cost), sid, sheet_id) of the best valid sheet of the newest message of another live thread."""
    best = None
    for sid in _live(threads):
        if sid != skip:
            ev, std = threads[sid], standard_terms(threads[sid])
            for s in _sheets(ev):
                t = s.get("terms") or {}
                if s.get("term_sheet_id") and t.get("unit_price") is not None and must_haves_ok(case, t, std):
                    best = min(best or (math.inf, sid, None), (BetterAgent._est_c(case, ev, t, std, k), sid, s["term_sheet_id"]))
    return best


def _why(case, threads, d, rule):
    """Plain-dict log of a decision: the complete-package C (pessimistic end of the band) against c_open and the alternative."""
    out = {"rule": rule, "supplier_id": d.get("supplier_id")}
    try:
        ev = threads.get(d.get("supplier_id"))
        with _ensure_health(case):
            est = HEALTH.get()
            out["c_open"] = _num(BetterAgent()._open_c(case, threads))
            out["band"] = [round(est["full_cost"] * k, 2) for k in est["band"]] if est else None
            out["alternative"] = {"c_alt": _num(_c_alt(case)), "best_other_thread": (lambda b: _num(b[0]) if b else None)(_best_standing(case, threads, d.get("supplier_id")))}
            t = _sheet_of(ev, d) if ev else None
            out["c_offer"], out["c_breakdown"] = None, None
            if t and t.get("unit_price") is not None:
                std = standard_terms(ev)
                out["c_offer"] = _num(BetterAgent._est_c(case, ev, t, std))
                b = BetterAgent()  # C of the offer minus c_open, in each world of the band (negative: a saving there)
                out["vs_open"] = {w: _num(b._est_c(case, ev, t, std, k) - b._open_c(case, threads, k)) for w, k in zip(("lo", "mid", "hi"), (est["band"][0], 1, est["band"][1]) if est else (1, 1, 1))}
                with _scaled((est or {}).get("band", (1, 1))[1]):
                    out["c_breakdown"] = {k: round(v, 2) for k, v in cost_breakdown(case, t, std).items()}
    except Exception as e:  # a log line must never break a decision
        out["error"] = repr(e)
    return out


def _accept_ok(case, threads, sid, t):
    """May we accept `t`, the standing sheet of thread `sid`? In every world k of the band (lower end, centre, upper end: C is
    piecewise linear in k, so the ends suffice; an accept priced above the opening has a less sensitive health term, so the
    worst case can be the lower end) its C is within c_open and below the alternative, and no other thread's standing sheet
    is cheaper there. On a final_offer or our last message the centre world alone is enough: never walk when accepting is
    no worse than c_open."""
    ev, std, b = threads[sid], standard_terms(threads[sid]), BetterAgent()
    lo, hi = (HEALTH.get() or {}).get("band", (1, 1))

    def ok(k):
        c, other = b._est_c(case, ev, t, std, k), _best_standing(case, threads, sid, k)
        with _scaled(k):
            c_alt = _c_alt(case)  # the alternative in the same world as the offer
        return c <= b._open_c(case, threads, k) and c < c_alt and not (other and other[0] < c - 0.005)

    final = latest(ev).get("status") == "final_offer" or moves_left(case, ev) <= 1
    return ok(1) if final else all(ok(k) for k in dict.fromkeys((lo, 1, hi)))


def _vetoes(case, threads, r):
    """True: do not close with this decision (closing rule, inside BetterAgent / HealthScope only): the hold rule, or the
    sheet is not an acceptable best complete package (_accept_ok)."""
    if BetterAgent.HOLD_FOR_FINAL and _holds(case, threads, r):
        return True
    if not BetterAgent.GUARD_C_OPEN or not (t := _sheet_of(threads[r["supplier_id"]], r)):
        return False
    return not _accept_ok(case, threads, r["supplier_id"], t)


def _holds(case, threads, decision):
    """True: do not close on this thread yet (plain open offer, messages to spare, price still moving)."""
    ev = threads[decision["supplier_id"]]
    ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
          for m in _sup(ev) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
    repeated = len(ps) >= 2 and ps[-1] == ps[-2]
    return latest(ev).get("status") == "open" and moves_left(case, ev) >= BetterAgent.HOLD_MESSAGES and not repeated


class HealthScope:
    """Outermost wrapper: the health estimate and the hold rule apply to the WHOLE delegate chain (the guard's
    closing_move and accept checks too), not only to BetterAgent.decide."""

    def __init__(self, delegate):
        self.delegate = delegate

    def __getattr__(self, name):
        if name == "delegate":
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        token = HOLD.set(_vetoes)
        try:
            with _with_health(case, BetterAgent.HEALTH_ESTIMATE):
                d = self.delegate.decide(case, threads)
                if isinstance(d, dict) and d.get("message"):  # the wrappers inside may have changed the message: log the final one
                    d = {**d, "why": _why(case, threads, d, (d.get("why") or {}).get("rule") or "wrapper")}
                return d
        finally:
            HOLD.reset(token)


class BetterAgent(SimplifyAgent):
    BAND = True  # False: the centre estimate only (no uncertainty band)
    GUARD_C_OPEN = THIRD_SHEET = ANCHOR_BY_SHARE = CASH_SHORT_OFFER = LATE_ACCEPT = HEALTH_ESTIMATE = True
    HOLD_FOR_FINAL = False  # dead on the real bots: final_offer comes at a fixed message whatever we do
    LATE_MESSAGES, LATE_TOLERANCE, HOLD_MESSAGES = 2, 0.01, 3
    MATCH_FACTOR = 1.0  # our step answers their last move in full (simplify: 0.25): the bot's last concession scales with our last step

    def decide(self, case, threads):
        token = HOLD.set(_vetoes)
        try:
            with _with_health(case, self.HEALTH_ESTIMATE):
                if self.LATE_ACCEPT and (late := self._late_accept(case, threads)):
                    d, rule = self._guard(case, threads, late), "late_accept"
                else:
                    d = super().decide(case, threads)
                    rule = {"accept": "accept", "walk_away": "walk_away"}.get(((d.get("message") or {}).get("action") or {}).get("type"), "counter")
                    d = self._guard(case, threads, d)
                return {**d, "why": _why(case, threads, d, (d.get("why") or {}).get("rule") or rule)}
        finally:
            HOLD.reset(token)

    # 0. never offer or accept above c_open ------------------------------------------------------------------
    @staticmethod
    def _est_c(case, events, t, std, k=None):
        """C of a sheet at the pessimistic end of the band (k: another multiple of the full cost), with the supplier's margin priced when the case charges for it."""
        with _ensure_health(case):
            return _c_at(case, t, std, k)

    def _open_c(self, case, threads, k=None):
        out = math.inf
        for ev in threads.values():
            std = standard_terms(ev)
            for m in _sup(ev):
                if m.get("term_sheets"):
                    for s in m["term_sheets"]:
                        t = s.get("terms") or {}
                        if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                            out = min(out, self._est_c(case, ev, t, std, k))  # c_open in the same world as the offer it is compared with
                    break
        return out

    def _fits(self, case, threads, cap=math.inf):
        """fits(events, t, std): our own offer t is no worse than the opening package in the centre AND the optimistic world
        (it may lose in the pessimistic one - that world is a hard rule for accepts only, see _accept_ok) and at the centre costs <= cap."""
        lo = (HEALTH.get() or {}).get("band", (1, 1))[0]
        opens = {k: self._open_c(case, threads, k) for k in dict.fromkeys((lo, 1))}
        return lambda ev, t, std: all(self._est_c(case, ev, t, std, k) <= c for k, c in opens.items()) and self._est_c(case, ev, t, std, 1) <= cap

    def _repair(self, case, events, std, t, fits, top):
        """The sheet with the lowest price >= its own that `fits` (up to `top`), else None."""
        if fits(events, t, std):
            return t
        lo = t["unit_price"]
        for i in range(1, 101):
            v = {**t, "unit_price": round(lo + (top - lo) * i / 100, 2)}
            if fits(events, v, std):
                return v
        return None

    def _guard(self, case, threads, d):
        if not self.GUARD_C_OPEN:
            return d
        sid, msg = d.get("supplier_id"), d.get("message") or {}
        ev = threads.get(sid)
        if not ev:
            return d
        std, fits = standard_terms(ev), self._fits(case, threads)
        act = msg.get("action") or {}
        accepting = act.get("type") == "accept"
        if act.get("type") == "walk_away":
            return self._not_walk(case, ev, sid, std, fits) or d
        if accepting:
            theirs = find_sheet(ev, act.get("term_sheet_id"))
            if theirs is None or _accept_ok(case, threads, sid, theirs):
                return d
            other = _best_standing(case, threads, sid)  # the best complete package wins, whatever the thread
            if other and _accept_ok(case, threads, other[1], find_sheet(threads[other[1]], other[2])):
                return {"supplier_id": other[1], "message": {"action": {"type": "accept", "term_sheet_id": other[2]}}, "why": {"rule": "accept_best_package"}}
            fits = self._fits(case, threads, _c_alt(case) - 0.01)  # the counter must also beat the alternative
            base = {k: std[k] for k in case["negotiable"] if k in std}
            sheets = [complete_offer(case, {**base, **theirs})]
        elif msg.get("term_sheets"):
            sheets = [s["terms"] for s in msg["term_sheets"]]
        else:
            return d
        first = next((m["term_sheets"][0]["terms"]["unit_price"] for m in _sup(ev) if m.get("term_sheets")), 0)
        fixed = [r for t in sheets if (r := self._repair(case, ev, std, t, fits, max(first, t["unit_price"])))]
        if fixed == sheets and not accepting:
            return d
        if not fixed and (counter := self._not_walk(case, ev, sid, std, fits)):  # no sheet fits: their own terms at the best fitting price
            return counter
        body = {"subject": case.get("title", "Our proposal"), "body": "Thank you for your offer. Please see our updated terms."}
        return {"supplier_id": sid, "message": {**body, "term_sheets": [{"terms": t} for t in fixed]} if fixed else
                {"subject": body["subject"], "body": "Could you please send us your best terms?"}, "why": {"rule": "guard_repair"}}

    def _not_walk(self, case, ev, sid, std, fits):
        """Instead of a walk: a counter at the supplier's own terms, priced at the lowest expected-C price in [its ask, its
        opening] that `fits` (a price above the health floor can beat the opening); None if there is none."""
        sheet_id, t = standing(ev)
        if not sheet_id or t.get("unit_price") is None or moves_left(case, ev) < 1:
            return None
        ask = t["unit_price"]
        top = max(ask, next((m["term_sheets"][0]["terms"]["unit_price"] for m in _sup(ev) if m.get("term_sheets")), ask))
        grid = [round(ask + (top - ask) * i / 100, 2) for i in range(101)]
        # their terms, or the same without an index clause (a clause they attach can cost more than the price gap)
        variants = [t, {**t, "index_clause": None}] if t.get("index_clause") and "index_clause" in case["negotiable"] else [t]
        safe = [v for u in variants for x in grid if fits(ev, v := {**u, "unit_price": x}, std)]
        if not safe:
            return None
        v = min(safe, key=lambda v: _exp_c(case, v, std))  # of those, the lowest expected C
        sheet = complete_offer(case, satisfy_must_haves(case, v, std))
        return {"supplier_id": sid, "message": {"subject": case.get("title", "Our proposal"),
                                                "body": "Thank you for your offer. Please see our final terms.", "term_sheets": [{"terms": sheet}]}, "why": {"rule": "not_walk"}}

    # 6. late accept ----------------------------------------------------------------------------------------
    def _late_accept(self, case, threads):
        c_alt = _c_alt(case)
        known, cand = math.inf, None
        for sid in _live(threads):
            ev, std = threads[sid], standard_terms(threads[sid])
            for s in _sheets(ev):
                if (t := s.get("terms") or {}).get("unit_price") is not None and must_haves_ok(case, t, std):
                    known = min(known, self._est_c(case, ev, t, std))
            sheet_id, t = standing(ev)
            if sheet_id and moves_left(case, ev) <= self.LATE_MESSAGES and t.get("unit_price") is not None and must_haves_ok(case, t, std):
                c = self._est_c(case, ev, t, std)
                if c < c_alt and _accept_ok(case, threads, sid, t):
                    cand = min(cand or (c, sid, sheet_id), (c, sid, sheet_id))
        if cand and cand[0] <= (1 + self.LATE_TOLERANCE) * known:
            return {"supplier_id": cand[1], "message": {"action": {"type": "accept", "term_sheet_id": cand[2]}}}
        return None

    # 3. cost-share anchor -----------------------------------------------------------------------------------
    @staticmethod
    def _share_factor(case):
        """1 - share x drop for the best index driver the case shows falling (index_paths < 0), else None."""
        paths = case["buyer"].get("index_paths") or {}
        hits = [c["material_share"] * -paths[c["series"]] for c in (case.get("term_options") or {}).get("index_clause", [])
                if c and paths.get(c["series"], 0) < 0]
        return 1 - max(hits) if hits else None

    def _price(self, case, events, p):
        if self.ANCHOR_BY_SHARE and not _mine(events) and not _health_at_stake(case) and (f := self._share_factor(case)):
            return max(ANCHOR_FLOOR * p, min(f * p, case["buyer"].get("current_unit_price") or p))
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            return super()._price(case, events, p)
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:
            step = max(MOVING_MIN * p, _tick(p), min(step, self.MATCH_FACTOR * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return min(p, max(mine[-1], min(top, mine[-1] + step)))  # never above their standing price

    # 2 + 5. third equivalent sheet / cash-short -------------------------------------------------------------
    @staticmethod
    def _cash_short(case, events):
        text = " ".join([*(m.get("body") or "" for m in _sup(events)), str(case.get("suppliers", ""))])
        return bool(CASH_SHORT.search(text))

    def _trade_sheet(self, case, events, std, main, p, pins, seen):
        """Same C as main with another lever: shorter payment days (or another contract length) for a lower price."""
        short = self.CASH_SHORT_OFFER and self._cash_short(case, events)
        levers = ("payment_days",) if short else ("payment_days", "contract_months") if self.THIRD_SHEET else ()
        opts, best = case.get("term_options") or {}, None
        cost = lambda t: total_cost(case, t, std)  # noqa: E731
        for f in levers:
            if f not in case["negotiable"] or f in pins or (_health_at_stake(case) and f not in FREE_LEVERS):
                continue
            for o in (o for o in opts.get(f, []) if o and o != main.get(f) and (f != "payment_days" or o < main[f])):
                t = satisfy_must_haves(case, {**main, f: o}, std)
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
                if t.get(f) != o or slope <= 0:
                    continue
                price = round(min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01), 2)
                v = {**t, "unit_price": price}
                if price > 0.75 * p and v not in seen and v != main and (best is None or price > best["unit_price"]):
                    best = v
            if best:
                break
        return best

    def _sheets(self, case, events, std, theirs):
        out = super()._sheets(case, events, std, theirs)
        if out and HEALTH.get():  # health cases: payment days as a lever, never below the C-minimising price, an index-clause sheet
            seen = [s["terms"] for m in _mine(events) for s in m.get("term_sheets") or []]
            opts, pins, p = case.get("term_options") or {}, _pinned(events), theirs["unit_price"]

            def best(t):  # t at the price in [its price, theirs] that minimises C
                grid = [round(t["unit_price"] + (p - t["unit_price"]) * i / 100, 2) for i in range(101)]
                return min(({**t, "unit_price": x} for x in grid), key=lambda v: _exp_c(case, v, std))

            pay = [o for o in opts.get("payment_days", []) if o] if "payment_days" in case["negotiable"] and "payment_days" not in pins else []
            fixed = []
            for t in out:
                t = min((best({**t, "payment_days": o}) for o in dict.fromkeys([t.get("payment_days"), *pay]) if o is not None), key=lambda v: _exp_c(case, v, std), default=best(t))
                if (t := complete_offer(case, t)) not in fixed and t not in seen:
                    fixed.append(t)
            out = fixed
            clauses = [c for c in opts.get("index_clause", []) if c] if "index_clause" in case["negotiable"] and "index_clause" not in pins else []
            if out and clauses:  # the clause sheet at its own C-minimising price, even when its C is not below main's
                v = complete_offer(case, min((best({**out[0], "index_clause": c}) for c in clauses), key=lambda v: _exp_c(case, v, std)))
                if v not in out and v not in seen:
                    out.append(v)
        if out and (self.THIRD_SHEET or self.CASH_SHORT_OFFER):
            seen = [s["terms"] for m in _mine(events) for s in m.get("term_sheets") or []]
            if extra := self._trade_sheet(case, events, std, out[0], theirs["unit_price"], _pinned(events), seen):
                if (extra := complete_offer(case, extra)) not in out:
                    out.append(extra)
        return out

"""The Reciprocal Bargainer: moves a visible step every round, in step with the supplier, and closes.

Why (30 real practice runs): suppliers answer visible moves with moves and send `final_offer` when
we idle (anchors ~20% below their price that then crept 0.01-0.03 a round scored 0.03-0.1), while an
agent that moved +2-3 EUR every round scored 0.94. And one run lost a 28.00 / 30 d / lead 35 deal
(best, must-have met) by re-asking for 90 days until the supplier walked: score 0.

- `closing_accept` (reusable; `ClosingAgent(delegate)` adds it to any agent): evaluate EVERY sheet of
  every live thread (alternatives `offer:..-a` too) with total_cost; take the cheapest that keeps the
  must-haves, beats the case alternative and is no worse than the thread's opening quote; accept it
  when the supplier says final_offer/agreed, or met our last price, or repeated itself (after >= 3 of
  our messages), or it is our last allowed message.
- `ReciprocalAgent`: anchor at 0.80 x their best standing price (0.75 floor, never above our current
  price when they ask for more), then every round close 25% (rising by 5 points a round, cap 50%) of the
  gap to their best standing price, at least 1% of price (while they move: at most 0.25 x their last
  move, at least 0.2%: the local simulator pays for patience, real suppliers for visible steps), but not closer than 3% to it before the last
  two messages (the supplier then ends with final_offer and we accept); never the same sheet twice; two sheets per
  message (main: the best contract length, payment and index option we may ask; variant: their own
  payment / index terms at the same price).
"""

import logging
import math
import re

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import ENDED, closing_move, latest, moves_left, standing

log = logging.getLogger("arena")

ANCHOR, ANCHOR_FLOOR = 0.80, 0.75  # first offer: x their best standing price (0.90 was met at once in 3 real runs)
FRAC0, FRAC_STEP, FRAC_MAX, MIN_STEP = 0.25, 0.05, 0.50, 0.01
KEEP = 0.05  # stay this far below their price until the last two messages (they end with final_offer, we accept)
MOVING_MIN = 0.002  # smallest step (x price) while they move; MIN_STEP when they hold still
MATCH = 0.25  # while they move, our step is at most this x their last move
REPEAT_AFTER = 3  # our messages before "the supplier repeated its sheet twice" means it has stalled
LIMIT = re.compile(r"(?:limit|stick to|only with|stay at|must stay|have to)[^.\n]{0,40}?(\d+)\s*days", re.I)
PAYMENT = re.compile(r"\b(?:payment|net|zahlungsziel)\b", re.I)
SENTENCE = re.compile(r"[.!?\n](?!\d)")  # not the point of 28.00
PINNABLE = ("payment_days", "lead_time_days", "contract_months")


def _tick(price):
    """The smallest visible price step: a cent, or 0.1% of the price when prices are large (per 100 / 1000 pieces)."""
    return max(0.01, 0.001 * price)


def _sup(events):
    return [m for m in events if m.get("from") != "buyer"]


def _mine(events):
    return [m for m in events if m.get("from") == "buyer"]


def _sheets(events):
    """Sheets of the supplier's newest message that has any (look back past question-only replies)."""
    return next((m["term_sheets"] for m in reversed(_sup(events)) if m.get("term_sheets")), [])


def _live(threads):
    """Threads with a supplier message that have not ended."""
    return [s for s, ev in threads.items() if _sup(ev) and latest(ev).get("status") not in ENDED]


def _c_alt(case):
    alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
    return total_cost(case, alt) if alt.get("unit_price") else math.inf


def case_c_open(case, threads):
    """C of the best opening: the cheapest first-message sheet (alternatives too) of ANY thread, ended
    ones included, that keeps the must-haves. A deal must beat it: a deal worse than the opening scores 0."""
    out = math.inf
    for ev in threads.values():
        first = next((m["term_sheets"] for m in _sup(ev) if m.get("term_sheets")), [])
        std = standard_terms(ev)
        for s in first:
            t = s.get("terms") or {}
            if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                out = min(out, total_cost(case, t, std))
    return out


def _valid(case, events, std, c_alt, musts=True):
    """[(C, sheet)] of the thread's standing sheets that keep the must-haves (unless musts=False), beat the alternative."""
    out = []
    for s in _sheets(events):
        t = s.get("terms") or {}
        if t.get("unit_price") is not None and s.get("term_sheet_id") and (not musts or must_haves_ok(case, t, std)):
            if (c := total_cost(case, t, std)) < c_alt:
                out.append((c, s))
    return out


def _ready(case, events, sheet):
    if latest(events).get("status") in ("final_offer", "agreed") or moves_left(case, events) <= 1:
        return True
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if not mine:
        return False
    price = sheet["terms"]["unit_price"]
    if price <= max(s["terms"].get("unit_price") or 0 for s in mine[-1]["term_sheets"]):
        return True  # they met us
    sup = [[s["terms"] for s in m["term_sheets"]] for m in _sup(events) if m.get("term_sheets")]
    return len(mine) >= REPEAT_AFTER and len(sup) >= 2 and sup[-1] == sup[-2]  # every sheet repeated, alternatives too


def _copy_sheet(case, events, std, sheet):
    """Our own term sheet with exactly the terms of one of theirs (to make it the standing sheet)."""
    base = {k: std[k] for k in case["negotiable"] if k in std}
    return complete_offer(case, {**base, **sheet["terms"]})


def _all_heard(case, threads):
    """Several live suppliers: each has had 2 of our messages, or is final / agreed, or is nearly out of messages."""
    live = _live(threads)
    return len(live) < 2 or all(
        len(_mine(threads[s])) >= 2 or latest(threads[s]).get("status") in ("final_offer", "agreed") or moves_left(case, threads[s]) <= 1
        for s in live
    )


def closing_accept(case, threads, c_open=None):
    """The decision that closes on the cheapest acceptable sheet when the rule says so, else None: an accept of
    the thread's standing sheet, or, when the best sheet is another one (an alternative `-a`, or one before a
    question-only reply), our term sheet with its exact terms - the supplier then agrees on a standing sheet."""
    c_alt, best, order = _c_alt(case), None, {s: i for i, s in enumerate(threads)}
    if not _all_heard(case, threads):
        return None
    c_open = case_c_open(case, threads) if c_open is None else c_open
    for sid in _live(threads):
        ev = threads[sid]
        for c, s in _valid(case, ev, standard_terms(ev), c_alt):
            if s["term_sheet_id"] != standing(ev)[0] and moves_left(case, ev) <= 1:
                continue  # our last message: only a standing sheet can still be accepted (a copy would be swapped away)
            if c < c_open:
                cand = (c, order[sid], sid, s["term_sheet_id"])  # ties: the thread that arrived first
                best = min(best or cand, cand)
    if best is None:
        return None
    _, _, sid, sheet_id = best
    events = threads[sid]
    sheet = next(s for s in _sheets(events) if s["term_sheet_id"] == sheet_id)
    if not _ready(case, events, sheet):
        return None
    if sheet_id == standing(events)[0]:
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
    copy = _copy_sheet(case, events, standard_terms(events), sheet)
    if any(s["terms"] == copy for m in _mine(events) for s in m.get("term_sheets") or []):
        return None  # sent already and not agreed: let the agent carry on
    return {"supplier_id": sid, "message": {"subject": case.get("title", "Our proposal"), "body": "We accept these terms; please confirm.", "term_sheets": [{"terms": copy}]}}


class ClosingAgent:
    """Adds only the accept rule to any agent."""

    def __init__(self, delegate):
        self.delegate = delegate

    def __getattr__(self, name):
        if name == "delegate":
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        try:
            if accept := closing_accept(case, threads):
                return accept
        except Exception:
            log.exception("%s closing rule failed", case.get("case_id"))
        return self.delegate.decide(case, threads)


def _pinned(events):
    """Terms the supplier will not move: repeated by it twice while we asked otherwise, or stated as a limit."""
    pins = {}
    sup = [m["term_sheets"][0]["terms"] for m in _sup(events) if m.get("term_sheets")]
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if len(sup) >= 2 and mine:
        for f in PINNABLE:
            asked = {s["terms"].get(f) for s in mine[-1]["term_sheets"]} - {None, sup[-1].get(f)}
            if sup[-1].get(f) is not None and sup[-1].get(f) == sup[-2].get(f) and asked:
                pins[f] = sup[-1][f]
    for m in _sup(events)[-2:]:
        for sentence in SENTENCE.split(m.get("body") or ""):
            if (hit := LIMIT.search(sentence)) and PAYMENT.search(sentence):
                pins["payment_days"] = int(hit.group(1))
    return pins


class ReciprocalAgent:
    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min(ANCHOR * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    @staticmethod
    def _index_variant(case, main, p, opts, pins, make, cost, cap, seen):
        """An index clause is security for the supplier, not cash: offer it for the price at which our C is just
        below the main sheet's C (the clause's expected cost per unit taken off the price). None if not negotiable."""
        if "index_clause" not in case["negotiable"] or "index_clause" in pins:
            return None
        best = None
        for clause in (c for c in opts.get("index_clause", []) if c):
            t = make(main["unit_price"], index_clause=clause, **{f: main[f] for f in ("payment_days", "contract_months") if f in main})
            if t["index_clause"] != clause or t["index_clause"] == main.get("index_clause"):
                continue
            slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
            if slope <= 0:
                continue
            price = round(max(0.75 * p, min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01)), 2)  # no lowball
            v = cap({**t, "unit_price": price})
            if 0 < price and v not in seen and cost(v) < cost(main) and (best is None or v["unit_price"] > best["unit_price"]):
                best = v
        return best

    def _sheets(self, case, events, std, theirs):
        p, pins = theirs["unit_price"], _pinned(events)
        base = {k: v for k, v in {**{f: std[f] for f in case["negotiable"] if f in std}, **theirs}.items() if v is not None}
        opts = case.get("term_options") or {}
        c_alt = _c_alt(case)
        sent = [m["term_sheets"] for m in _mine(events) if m.get("term_sheets")]
        seen = [s["terms"] for ss in sent for s in ss]

        def make(price, **over):
            over = {k: v for k, v in over.items() if k not in pins}
            return satisfy_must_haves(case, {**base, "unit_price": round(price, 2), **over}, std)

        def cost(t):
            return total_cost(case, t, std)

        def cap(t):  # hard floor: never offer a sheet that costs more than the alternative
            if (c := cost(t)) >= c_alt:
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - c
                if slope > 0:
                    t = {**t, "unit_price": round(t["unit_price"] - (c - c_alt) / slope - 0.01, 2)}
            return t

        def best_months(price, **over):
            months = [m for m in opts.get("contract_months", []) if m and "contract_months" in case["negotiable"]] or [None]
            return min(months, key=lambda m: (cost(make(price, **over, **({"contract_months": m} if m else {}))), m or 0))

        fields = [f for f in ("payment_days", "index_clause") if f in case["negotiable"] and f not in pins and opts.get(f)]
        combos = [{}]
        for f in fields:
            combos = [{**v, f: o} for v in combos for o in opts[f]]

        def pair(price):
            """(main, variant): main asks for the cheapest payment/index option, variant keeps their own."""
            months = best_months(price)
            mk = lambda v: cap(make(price, **({"contract_months": months} if months else {}), **v))  # noqa: E731
            theirs, asks = mk({}), [mk(v) for v in combos]
            main = min(asks, key=cost)
            return main, theirs

        price = self._price(case, events, p)
        main, theirs = pair(price)
        floor = max((x["terms"]["unit_price"] for ss in sent for x in ss[:1] if x["terms"].get("unit_price")), default=0.0)
        while (main in seen or main["unit_price"] <= floor) and price < p:  # always a visible step, never a repeat, never above theirs
            price = min(p, price + _tick(p))
            new, theirs = pair(price)
            if new == main:  # capped: the price cannot move
                break
            main = new
        if main in seen:
            return []
        out = [main] + ([theirs] if theirs != main and theirs not in seen else [])
        if (extra := self._index_variant(case, main, p, opts, pins, make, cost, cap, seen)) and extra not in out:
            out.append(extra)
        return [complete_offer(case, t) for t in out]

"""Score agents against the real-like local arena: every case x seed, no API, no credits.

    python -m arena_kit.evaluate --agents guarded_rational,confident_router --set dev --seeds 5

--set dev|test: the generated cases (gen_cases.py; tune on dev, score on test once); real: the 10 hosted
real practice cases, plus a comparison with the scores the same agents really got (sim_cases/real_runs).
It starts arena-sim itself on a free local port (one server per seed, the suppliers' draws follow the seed),
plays with the kit's own client and agents, and stops the servers at the end. It refuses a non-local
ARENA_URL and the `llm` agent (it would call a model API). Reads local files only.
"""

import argparse
import json
import os
import socket
import statistics as st
import threading
import time
from collections import defaultdict
from pathlib import Path
from urllib.parse import urlparse

from .cli import AGENTS, agent_factory
from .client import ArenaClient
from .fit_real import load_split
from .play import RemoteTable, hosted, play_all
from .sim import CASES, load_cases
from .sim_real import PROFILE, SimReal

LOCAL = {"127.0.0.1", "localhost", "::1"}
DEFAULT_DATA = Path.home() / "Documents/Codex/negotiation-arena-kit/data"


def check_local():
    url = os.environ.get("ARENA_URL")
    if url and urlparse(url).hostname not in LOCAL:
        raise SystemExit(f"refusing to run: ARENA_URL={url} is not local; evaluate only talks to its own simulator")


class Server:
    """arena-sim with the real-like supplier, on a free local port, in a thread."""

    def __init__(self, sim):
        import uvicorn

        from .sim import create_app

        with socket.socket() as s:
            s.bind(("127.0.0.1", 0))
            self.port = s.getsockname()[1]
        self.server = uvicorn.Server(
            uvicorn.Config(create_app(sim), host="127.0.0.1", port=self.port, log_level="error")
        )
        self.thread = threading.Thread(target=self.server.run, daemon=True)

    def __enter__(self):
        self.thread.start()
        for _ in range(200):
            if self.server.started:
                return f"http://127.0.0.1:{self.port}"
            time.sleep(0.05)
        raise RuntimeError("the simulator did not start")

    def __exit__(self, *exc):
        self.server.should_exit = True
        self.thread.join(10)


def case_folder(which):
    return {"dev": CASES / "gen_dev", "test": CASES / "gen_test", "real": CASES / "real"}[which]


def split_ids(split):
    """The real-case ids of a split (`holdout.json`): unseen = reserved, train = the rest, all = None (no filter)."""
    from .fit_real import load_split

    return None if split == "all" else {f"case:{c}" for c in load_split()[split]}


def play_set(agents, which, seeds, data, parallel, profile=None, only=None):
    """(cases, {agent: {(case_id, seed): score}}, {agent: [(case_id, seed) of crashed games]})"""
    cases = load_cases(case_folder(which))
    ids = [c["case_id"] for c in hosted(list(cases.values())) if only is None or c["case_id"] in only]
    facts = {}
    if data and (Path(data) / "facts.json").is_file():
        from .data import DataPackage

        facts = DataPackage(data).facts
    else:
        print(
            f"WARNING: no data package at {data!r} (--data): cited IDs cannot be verified and evidence agents degrade"
        )
    out = {a: {} for a in agents}
    crashed = {a: [] for a in agents}
    for seed in range(seeds):
        sim = SimReal(
            cases, facts, "sim", no_clock=True, seed=seed, profile=profile
        )  # no 60 s rule: agents here are fast
        sim.max_calls = 10**9  # and no 10-calls-per-second limit: one machine plays many games at once
        with Server(sim) as url:
            for name in agents:
                key = ArenaClient(url, api_key="x").register(f"{name}-{seed}", "sim")["api_key"]
                client = ArenaClient(url, key, rate=1000)
                done = play_all(lambda client=client: RemoteTable(client), ids, agent_factory(name, data), parallel)
                for cid, r in done.items():
                    if isinstance(r, dict):
                        out[name][(cid, seed)] = r.get("score") or 0.0
                    else:  # a crashed game is not a score of 0: it is left out of the means and counted
                        crashed[name].append((cid, seed))
                        print(f"  CRASHED {name} {cid} seed {seed}: {r!r}")
    return cases, out, crashed


def mean(xs):
    return st.mean(xs) if xs else float("nan")


def report(cases, scores, crashed):
    print(f"\n{'agent':20} {'mean':>6} {'deal>0':>7} {'crashed':>8} {'worst case (mean over seeds)':>34}")
    for a, res in scores.items():
        per_case = defaultdict(list)
        for (cid, _), v in res.items():
            per_case[cid].append(v)
        worst = min(per_case, key=lambda c: mean(per_case[c]))
        allv = list(res.values())
        print(
            f"{a:20} {mean(allv):6.3f} {mean([v > 0 for v in allv]):7.2f} {len(crashed[a]):8d} "
            f"{worst:>22} {mean(per_case[worst]):6.3f}"
        )
    types = sorted({c["type"] for c in cases.values()})
    print(f"\n{'mean score by case type':24}" + "".join(f"{a[:14]:>16}" for a in scores))
    for t in types:
        row = []
        for res in scores.values():
            row.append(mean([v for (cid, _), v in res.items() if cases[cid]["type"] == t]))
        print(f"{t:24}" + "".join(f"{x:16.3f}" for x in row))


def real_scores(dirs=None):
    """The scores the agents really got on the practice arena: {(agent, 'case:Pxx'): mean score of its runs}."""
    from .fit_real import ALL_DIRS, dumps

    runs = defaultdict(list)
    for d in dumps(dirs or ALL_DIRS):
        runs[(d["agent"], f"case:{d['case']}")].append(d["result"]["score"])
    return {k: mean(v) for k, v in runs.items()}


def compare(cases, scores):
    real = real_scores()
    agents = [a for a in scores if any(k[0] == a for k in real)]
    rows = []
    for a in agents:
        for cid in sorted({c for (x, c) in real if x == a}):
            ms = [v for (c, _), v in scores[a].items() if c == cid]
            if ms:  # the case was played (a --split leaves the others out)
                rows.append((a, cid, real[(a, cid)], mean(ms)))
    fit = json.loads(PROFILE.read_text(encoding="utf-8"))["meta"].get("split", "unknown (profile not fitted by fit_real.py)")
    unseen = {f"case:{c}" for c in load_split()["unseen"]}
    print(f"\nMOCK vs REAL (same agents, hosted cases; real = mean over all dumps of the agent). Profile: {fit}")
    for name, part in (("TRAIN (in-sample: checks the fit)", [x for x in rows if x[1] not in unseen]),
                       ("UNSEEN (reserved cases: the mock's predictive power)", [x for x in rows if x[1] in unseen])):  # fmt: skip
        if not part:
            continue
        err = mean([abs(r - m) for _, _, r, m in part])
        cor = st.correlation([x[2] for x in part], [x[3] for x in part]) if len(part) > 2 else float("nan")
        print(f"{name}: MAE {err:.3f}, correlation {cor:.2f} over {len(part)} (agent, case) pairs")
        for a in agents:
            r = [x[2] for x in part if x[0] == a]
            if r:
                print(f"  {a:20} real {mean(r):6.3f} mock {mean([x[3] for x in part if x[0] == a]):6.3f}")
    print("biggest mismatches (agent, case, real, mock):")
    for a, cid, r, m in sorted(rows, key=lambda x: -abs(x[2] - x[3]))[:8]:
        print(f"  {a:20} {cid:10} {r:6.3f} {m:6.3f}{'  (unseen)' if cid in unseen else ''}")


def holdout(
    agents, seeds, data, parallel, fit_dirs=("real_runs", "real_runs_v16"), test_dirs=("real_runs_v17", "real_runs_v19")
):
    """HOLD-OUT: fit the supplier on `fit_dirs` only, play the mock, compare with the real scores of `test_dirs`."""
    import copy

    from .fit_real import dumps, fit, to_parameters

    prof = copy.deepcopy(json.loads(PROFILE.read_text(encoding="utf-8")))
    prof["parameters"].update(to_parameters(fit(list(fit_dirs), prof), sum(1 for _ in dumps(fit_dirs))))
    real = real_scores(list(test_dirs))
    agents = [a for a in agents if any(k[0] == a for k in real)]
    cases, scores, _ = play_set(agents, "real", seeds, data, parallel, prof["parameters"])
    errs = []
    print(f"\nHOLD-OUT: profile fitted on {list(fit_dirs)}, predicting {list(test_dirs)}")
    for (a, cid), r in sorted(real.items()):
        if a in scores:
            m = mean([v for (c, _), v in scores[a].items() if c == cid])
            errs.append(abs(r - m))
            print(f"  {a:20} {cid:10} real {r:6.3f} mock {m:6.3f} abs err {errs[-1]:.3f}")
    print(f"hold-out mean abs error of the score per (agent, case): {mean(errs):.3f} over {len(errs)} pairs")


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--agents", default="guarded_rational,confident_router")
    ap.add_argument("--set", choices=["dev", "test", "real"], default="dev")
    ap.add_argument("--seeds", type=int, default=5)
    ap.add_argument("--data", default=os.environ.get("ARENA_DATA") or str(DEFAULT_DATA))
    ap.add_argument("--split", choices=["unseen", "train", "all"], default="all", help="--set real only: which cases (holdout.json)")
    ap.add_argument("--holdout", action="store_true", help="fit on real_runs+v16 only, predict the v17 and v19 dumps")
    ap.add_argument("--parallel", type=int, default=8)
    a = ap.parse_args(argv)
    check_local()
    agents = a.agents.split(",")
    bad = [x for x in agents if x not in AGENTS or x == "llm"]
    if bad:
        raise SystemExit(
            f"unknown or not allowed (llm calls a model API): {bad}; choose from {[x for x in AGENTS if x != 'llm']}"
        )
    if a.holdout:
        return holdout(agents, a.seeds, a.data, a.parallel)
    if a.split != "all" and a.set != "real":
        raise SystemExit("--split applies to --set real only")
    only = split_ids(a.split) if a.set == "real" else None
    if a.set == "real" and json.loads(PROFILE.read_text(encoding="utf-8"))["meta"].get("split", "").startswith("all"):
        print("profile fitted on all real runs: --split unseen is in-sample for the simulator")
    cases, scores, crashed = play_set(agents, a.set, a.seeds, a.data, a.parallel, only=only)
    report({k: v for k, v in cases.items() if v.get("hosted", True) and (only is None or k in only)}, scores, crashed)
    if a.set == "real":
        compare(cases, scores)


if __name__ == "__main__":
    main()

